#include <stdio.h>
#include <string.h>

#define MAX 100

// Define the Flight structure
struct Flight {
    int flightNumber;
    char source[30];
    char destination[30];
    char departure[10];
    char arrival[10];
};

// Global flight array and count
struct Flight flights[MAX];
int count = 0;

// Function to create flights
void create() {
    int n, i;
    printf("How many flights do you want to add? ");
    scanf("%d", &n);

    for(i = 0; i < n; i++) {
        printf("\nEnter details for flight %d:\n", i + 1);
        printf("Flight Number: ");
        scanf("%d", &flights[count].flightNumber);
        printf("Source: ");
        scanf("%s", flights[count].source);
        printf("Destination: ");
        scanf("%s", flights[count].destination);
        printf("Departure Time: ");
        scanf("%s", flights[count].departure);
        printf("Arrival Time: ");
        scanf("%s", flights[count].arrival);
        count++;
    }
}

// Function to display flights
void display() {
    int i;
    if(count == 0) {
        printf("\nNo flights to display.\n");
        return;
    }
    printf("\n--- Flight List ---\n");
    for(i = 0; i < count; i++) {
        printf("\nFlight %d:\n", i + 1);
        printf("Flight Number: %d\n", flights[i].flightNumber);
        printf("Source: %s\n", flights[i].source);
        printf("Destination: %s\n", flights[i].destination);
        printf("Departure Time: %s\n", flights[i].departure);
        printf("Arrival Time: %s\n", flights[i].arrival);
    }
}

// Function to insert a flight at a position
void insert() {
    int pos, i;
    if(count == MAX) {
        printf("\nCannot insert, list is full.\n");
        return;
    }

    printf("\nEnter position to insert (1 to %d): ", count + 1);
    scanf("%d", &pos);
    if(pos < 1 || pos > count + 1) {
        printf("Invalid position!\n");
        return;
    }

    for(i = count; i >= pos; i--) {
        flights[i] = flights[i - 1];
    }

    printf("Enter details for new flight:\n");
    printf("Flight Number: ");
    scanf("%d", &flights[pos - 1].flightNumber);
    printf("Source: ");
    scanf("%s", flights[pos - 1].source);
    printf("Destination: ");
    scanf("%s", flights[pos - 1].destination);
    printf("Departure Time: ");
    scanf("%s", flights[pos - 1].departure);
    printf("Arrival Time: ");
    scanf("%s", flights[pos - 1].arrival);
    count++;
    printf("Flight inserted successfully.\n");
}

// Function to delete a flight at a position
void delete() {
    int pos, i;
    if(count == 0) {
        printf("\nNo flights to delete.\n");
        return;
    }
    printf("\nEnter position to delete (1 to %d): ", count);
    scanf("%d", &pos);
    if(pos < 1 || pos > count) {
        printf("Invalid position!\n");
        return;
    }
    for(i = pos - 1; i < count - 1; i++) {
        flights[i] = flights[i + 1];
    }
    count--;
    printf("Flight deleted successfully.\n");
}

// Function to modify a flight
void modify() {
    int i, fnum, found = 0;
    if(count == 0) {
        printf("\nNo flights to modify.\n");
        return;
    }
    printf("\nEnter flight number to modify: ");
    scanf("%d", &fnum);
    for(i = 0; i < count; i++) {
        if(flights[i].flightNumber == fnum) {
            printf("Enter new details:\n");
            printf("Flight Number: ");
            scanf("%d", &flights[i].flightNumber);
            printf("Source: ");
            scanf("%s", flights[i].source);
            printf("Destination: ");
            scanf("%s", flights[i].destination);
            printf("Departure Time: ");
            scanf("%s", flights[i].departure);
            printf("Arrival Time: ");
            scanf("%s", flights[i].arrival);
            printf("Flight modified successfully.\n");
            found = 1;
            break;
        }
    }
    if(!found) {
        printf("Flight number not found.\n");
    }
}

// Function to sort flights by flight number
void sort() {
    int i, j;
    struct Flight temp;
    if(count == 0) {
        printf("\nNo flights to sort.\n");
        return;
    }
    for(i = 0; i < count - 1; i++) {
        for(j = i + 1; j < count; j++) {
            if(flights[i].flightNumber > flights[j].flightNumber) {
                temp = flights[i];
                flights[i] = flights[j];
                flights[j] = temp;
            }
        }
    }
    printf("Flights sorted by flight number.\n");
}

// Main menu
int main() {
    int choice;
    do {
        printf("\n--- Airline Management Menu ---\n");
        printf("1. Create Flights\n");
        printf("2. Display Flights\n");
        printf("3. Insert Flight\n");
        printf("4. Delete Flight\n");
        printf("5. Modify Flight\n");
        printf("6. Sort Flights\n");
        printf("7. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch(choice) {
            case 1: create(); break;
            case 2: display(); break;
            case 3: insert(); break;
            case 4: delete(); break;
            case 5: modify(); break;
            case 6: sort(); break;
            case 7: printf("Exiting program.\n"); break;
            default: printf("Invalid choice, try again.\n");
        }
    } while(choice != 7);

    return 0;
}Simplify the code

