### **Simplified C Code for Airline Management System**
```c
#include <stdio.h>
#include <string.h>

#define MAX 100

// Structure to store flight information
struct Flight {
    int number;
    char source[30];
    char destination[30];
    char departure[10];
    char arrival[10];
};

struct Flight flights[MAX];
int count = 0;

// Reusable function to input flight details
void inputFlight(struct Flight *f) {
    printf("Flight Number: ");
    scanf("%d", &f->number);
    printf("Source: ");
    scanf("%s", f->source);
    printf("Destination: ");
    scanf("%s", f->destination);
    printf("Departure Time: ");
    scanf("%s", f->departure);
    printf("Arrival Time: ");
    scanf("%s", f->arrival);
}

// Create multiple flights
void create() {
    int n;
    printf("How many flights to add? ");
    scanf("%d", &n);

    for(int i = 0; i < n && count < MAX; i++) {
        printf("\nEnter details for flight %d:\n", count + 1);
        inputFlight(&flights[count++]);
    }
}

// Display all flights
void display() {
    if(count == 0) {
        printf("\nNo flights to display.\n");
        return;
    }

    printf("\n--- Flight List ---\n");
    for(int i = 0; i < count; i++) {
        printf("\nFlight %d\n", i + 1);
        printf("Number: %d\n", flights[i].number);
        printf("Source: %s\n", flights[i].source);
        printf("Destination: %s\n", flights[i].destination);
        printf("Departure: %s\n", flights[i].departure);
        printf("Arrival: %s\n", flights[i].arrival);
    }
}

// Insert a flight at a given position
void insert() {
    if(count == MAX) {
        printf("\nList is full.\n");
        return;
    }

    int pos;
    printf("Enter position to insert (1 to %d): ", count + 1);
    scanf("%d", &pos);

    if(pos < 1 || pos > count + 1) {
        printf("Invalid position.\n");
        return;
    }

    for(int i = count; i >= pos; i--) {
        flights[i] = flights[i - 1];
    }

    printf("\nEnter details for new flight:\n");
    inputFlight(&flights[pos - 1]);
    count++;
    printf("Flight inserted.\n");
}

// Delete a flight at a position
void delete() {
    if(count == 0) {
        printf("\nNo flights to delete.\n");
        return;
    }

    int pos;
    printf("Enter position to delete (1 to %d): ", count);
    scanf("%d", &pos);

    if(pos < 1 || pos > count) {
        printf("Invalid position.\n");
        return;
    }

    for(int i = pos - 1; i < count - 1; i++) {
        flights[i] = flights[i + 1];
    }
    count--;
    printf("Flight deleted.\n");
}

// Modify a flight by its number
void modify() {
    if(count == 0) {
        printf("\nNo flights to modify.\n");
        return;
    }

    int fnum, found = 0;
    printf("Enter flight number to modify: ");
    scanf("%d", &fnum);

    for(int i = 0; i < count; i++) {
        if(flights[i].number == fnum) {
            printf("Enter new details:\n");
            inputFlight(&flights[i]);
            printf("Flight modified.\n");
            found = 1;
            break;
        }
    }

    if(!found) {
        printf("Flight not found.\n");
    }
}

// Sort flights by flight number
void sort() {
    if(count == 0) {
        printf("\nNo flights to sort.\n");
        return;
    }

    for(int i = 0; i < count - 1; i++) {
        for(int j = i + 1; j < count; j++) {
            if(flights[i].number > flights[j].number) {
                struct Flight temp = flights[i];
                flights[i] = flights[j];
                flights[j] = temp;
            }
        }
    }
    printf("Flights sorted.\n");
}

// Main menu
int main() {
    int choice;

    do {
        printf("\n--- Airline Management Menu ---\n");
        printf("1. Create Flights\n");
        printf("2. Display Flights\n");
        printf("3. Insert Flight\n");
        printf("4. Delete Flight\n");
        printf("5. Modify Flight\n");
        printf("6. Sort Flights\n");
        printf("7. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch(choice) {
            case 1: create(); break;
            case 2: display(); break;
            case 3: insert(); break;
            case 4: delete(); break;
            case 5: modify(); break;
            case 6: sort(); break;
            case 7: printf("Exiting.\n"); break;
            default: printf("Invalid choice.\n");
        }
    } while(choice != 7);

    return 0;
}
